--
-- Table structure for table `Order`
--

DROP TABLE IF EXISTS `Order`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `Order` (
  `id` int NOT NULL AUTO_INCREMENT,
  `productId` int NOT NULL,
  `buyerId` int NOT NULL,
  `sellerId` int NOT NULL,
  `status` enum('PENDING','IN_PROGRESS','WAITING_REVIEW','COMPLETED','CANCELED') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'PENDING',
  `meetupLocation` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `note` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `createdAt` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updatedAt` datetime(3) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `Order_productId_idx` (`productId`),
  KEY `Order_buyerId_status_updatedAt_idx` (`buyerId`,`status`,`updatedAt`),
  KEY `Order_sellerId_status_updatedAt_idx` (`sellerId`,`status`,`updatedAt`),
  KEY `Order_status_createdAt_idx` (`status`,`createdAt`),
  CONSTRAINT `Order_buyerId_fkey` FOREIGN KEY (`buyerId`) REFERENCES `User` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `Order_productId_fkey` FOREIGN KEY (`productId`) REFERENCES `Product` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
